const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v);
/** RumbleMgr::start(idx, repeat, f32* / Vec*): mult a number (the f32), a position, or null (1) */
export function rumbleStart(w: World, idx: number, repeat: number, mult: number | V3 | null) {
    let m = 1;
    if (typeof mult === 'number') m = clamp01(mult);
    else if (mult) { const d = Math.hypot(mult.x - w.mario.pos.x, mult.y - w.mario.pos.y, mult.z - w.mario.pos.z); m = clamp01(-((d - 300) * (1 / 3000) - 1)); }
    w.events.push({ t: w.tickCount, kind: 'rumble', data: { idx, repeat, mult: m } });
}
